"""Unit D: Object-oriented programming."""

from __future__ import annotations

from app.services.python_practice.content.build import mcq as M, out as O


def questions() -> list[dict]:
    return [
        O("classes-objects", "easy", "What is printed?", "class Dog:\n    pass\n\na, b = Dog(), Dog()\nprint(a == b, type(a).__name__, isinstance(a, Dog))", "False Dog True", ["True Dog True", "False Dog False", "False type True"], "Without __eq__, == falls back to identity, so two separate instances differ. type(a).__name__ is the class name."),
        M("classes-objects", "easy", "What is the relationship between a class and an object?", "A class is a blueprint; an object (instance) is created from it", ["An object is a blueprint; a class is an instance", "They are identical", "A class can only create one object"], "Calling the class creates instances, each with its own state."),
        O("init-constructors", "easy", "What is printed?", "class P:\n    def __init__(self, name):\n        self.name = name\n\np = P('Ada')\nprint(p.name, p.__init__ is not None)", "Ada True", ["None True", "Ada False", "TypeError"], "__init__ initialises the new instance created by __new__; it must return None."),
        O("init-constructors", "medium", "What happens when this code runs?", "class A:\n    def __init__(self):\n        return 5\n\nA()", "TypeError", ["It returns 5 from A()", "It prints 5", "AttributeError"], "__init__ must return None; returning anything else raises TypeError.", exc="TypeError"),
        O("method-kinds", "medium", "What is printed?", "class C:\n    n = 0\n    def inst(self): return 'i'\n    @classmethod\n    def cm(cls): return cls.__name__\n    @staticmethod\n    def sm(x): return x * 2\n\nprint(C().inst(), C.cm(), C.sm(4))", "i C 8", ["i C 4", "i self 8", "C C 8"], "Instance methods get self, class methods get the class (cls), static methods get nothing implicit."),
        M("method-kinds", "medium", "When is @classmethod the right choice?", "For alternative constructors or behaviour that needs the class (including subclasses) but no instance", ["When the method must modify instance attributes", "When you want to hide the method", "Whenever a method has no arguments"], "A classmethod receives cls, so `cls(...)` builds instances of whichever subclass was called."),
        O("attributes", "medium", "What is printed?", "class A:\n    items = []\n    def __init__(self):\n        pass\n\na, b = A(), A()\na.items.append(1)\nprint(b.items, A.items is b.items)", "[1] True", ["[] False", "[1] False", "[] True"], "A class attribute is shared by all instances; a.items.append mutates the shared list."),
        O("attributes", "medium", "What is printed?", "class A:\n    x = 1\n\na = A()\na.x = 2\nprint(A.x, a.x, A().x)", "1 2 1", ["2 2 2", "1 1 1", "2 2 1"], "Assigning through an instance creates an instance attribute that shadows the class attribute; the class value is unchanged."),
        O("encapsulation", "medium", "What is printed?", "class A:\n    def __init__(self):\n        self.__secret = 7\n\na = A()\nprint(hasattr(a, '__secret'), a._A__secret)", "False 7", ["True 7", "False AttributeError", "True AttributeError"], "A double leading underscore triggers name mangling to _ClassName__name. It discourages access but is not true privacy."),
        M("encapsulation", "easy", "What does a single leading underscore (_value) signal in Python?", "A convention that the attribute is internal and not part of the public API", ["The attribute is enforced as private by the interpreter", "The attribute is read-only", "The attribute is a class attribute"], "Python relies on convention; nothing prevents access."),
        O("inheritance", "easy", "What is printed?", "class A:\n    def hi(self): return 'A'\nclass B(A):\n    pass\n\nprint(B().hi(), issubclass(B, A), isinstance(B(), A))", "A True True", ["B True True", "A False True", "AttributeError"], "B inherits hi from A; issubclass and isinstance follow the inheritance chain."),
        M("inheritance", "medium", "Which relationship does inheritance model?", "'is-a': a subclass is a specialised kind of its base class", ["'has-a': one object contains another", "'uses-a': one function calls another", "'is-the-same-as'"], "Use inheritance for substitutable is-a relationships; use composition for has-a."),
        O("multiple-inheritance", "hard", "What is printed?", "class A:\n    def who(self): return 'A'\nclass B(A):\n    def who(self): return 'B'\nclass C(A):\n    def who(self): return 'C'\nclass D(B, C):\n    pass\n\nprint(D().who(), [k.__name__ for k in D.__mro__])", "B ['D', 'B', 'C', 'A', 'object']", ["A ['D', 'B', 'C', 'A', 'object']", "B ['D', 'B', 'A', 'C', 'object']", "C ['D', 'C', 'B', 'A', 'object']"], "C3 linearisation puts D, then its bases left to right, with the shared base A after both B and C."),
        M("multiple-inheritance", "medium", "What is the 'diamond problem' and how does Python handle it?", "Ambiguity when a class inherits the same base via two paths; the MRO (C3) gives one deterministic order", ["It crashes at import time; Python forbids it", "Python calls every base method automatically", "It only occurs with abstract classes"], "Python computes a linear Method Resolution Order, and cooperative super() calls follow it."),
        O("polymorphism", "easy", "What is printed?", "class Cat:\n    def speak(self): return 'meow'\nclass Dog:\n    def speak(self): return 'woof'\n\nprint([a.speak() for a in (Cat(), Dog())])", "['meow', 'woof']", ["['meow', 'meow']", "TypeError", "['Cat', 'Dog']"], "Duck typing: anything with a speak() method works; no shared base class is needed."),
        M("polymorphism", "medium", "Which best describes polymorphism?", "The same operation or interface works on objects of different types, each behaving appropriately", ["Hiding data inside a class", "Creating many instances of one class", "Copying an object"], "Calling speak() on different objects dispatches to each object's own implementation."),
        O("overriding", "medium", "What is printed?", "class A:\n    def f(self): return 'A.f'\n    def g(self): return self.f()\nclass B(A):\n    def f(self): return 'B.f'\n\nprint(B().g())", "B.f", ["A.f", "A.f B.f", "AttributeError"], "self.f() looks up f on the actual object's class, so the override in B is used even when called from A.g."),
        M("overriding", "easy", "What happens if a subclass defines a method with the same name as the base class?", "The subclass version is found first and overrides the base version for its instances", ["Python raises a NameError", "Both run automatically", "The base version always wins"], "Attribute lookup follows the MRO, subclass first."),
        M("composition", "medium", "A Car needs an Engine. Which design is usually better?", "Composition: Car holds an Engine instance and delegates to it", ["Car inherits from Engine", "Engine inherits from Car", "Engine is a global function"], "A car has an engine; it is not a kind of engine. Composition is more flexible and avoids deep hierarchies."),
        M("composition", "hard", "Which situation most favours composition over inheritance?", "You want to swap behaviour at runtime or combine several independent capabilities", ["You need to reuse every method of a very similar class unchanged", "You are modelling a strict is-a taxonomy", "You want to share class attributes"], "Holding collaborator objects lets you replace them and avoid tight coupling to a base class."),
        O("abc-interfaces", "medium", "What happens when this code runs?", "from abc import ABC, abstractmethod\nclass Shape(ABC):\n    @abstractmethod\n    def area(self): ...\n\nShape()", "TypeError", ["It creates a Shape with area() returning None", "NotImplementedError", "AttributeError"], "A class with unimplemented abstract methods cannot be instantiated.", exc="TypeError"),
        M("abc-interfaces", "medium", "How does typing.Protocol differ from an ABC?", "A Protocol is structural: matching method signatures suffice, with no inheritance required", ["A Protocol must always be inherited from", "A Protocol cannot have methods", "They are identical"], "Protocols describe what an object can do (static duck typing); ABCs enforce explicit inheritance or registration."),
        O("properties-descriptors", "medium", "What is printed?", "class T:\n    def __init__(self): self._c = 0\n    @property\n    def c(self): return self._c\n    @c.setter\n    def c(self, v):\n        if v < 0: raise ValueError\n        self._c = v\n\nt = T()\nt.c = 5\nprint(t.c)\ntry:\n    t.c = -1\nexcept ValueError:\n    print('bad')", "5\nbad", ["5\n5", "bad\nbad", "AttributeError"], "A property exposes attribute syntax while running validation in the setter."),
        M("properties-descriptors", "hard", "Which methods make an object a data descriptor?", "__get__ together with __set__ (or __delete__)", ["__init__ and __call__", "__getattr__ only", "__new__ and __del__"], "Data descriptors take precedence over instance attributes; property is a built-in data descriptor. Functions are non-data descriptors (only __get__)."),
        O("mro", "medium", "What is printed?", "class A: pass\nclass B(A): pass\nprint(B.__mro__[1].__name__, B.mro()[-1].__name__)", "A object", ["B object", "A A", "object A"], "The MRO lists the class, its bases in order, and finally object."),
        M("mro", "hard", "Which inheritance declaration raises TypeError for an inconsistent MRO?", "class X(A, B) where B already derives from A", ["class X(B, A) where B derives from A", "class X(A) only", "class X(object)"], "Listing a base before its own subclass has no valid C3 order. Put the more specific class first."),
        O("dunder-methods", "medium", "What is printed?", "class V:\n    def __init__(self, n): self.n = n\n    def __add__(self, o): return V(self.n + o.n)\n    def __repr__(self): return f'V({self.n})'\n    def __len__(self): return self.n\n\nv = V(2) + V(3)\nprint(v, len(v))", "V(5) 5", ["V(5) 2", "<V object> 5", "TypeError"], "+ calls __add__, print uses __repr__ when no __str__ exists, and len() calls __len__."),
        M("dunder-methods", "medium", "If a class defines __eq__ but not __hash__, what happens to its instances?", "They become unhashable (cannot be dict keys or set members)", ["They hash by identity as before", "Their hash becomes 0", "Defining __eq__ raises an error"], "Python sets __hash__ to None when __eq__ is defined without __hash__, to avoid inconsistent hashing."),
        O("super", "medium", "What is printed?", "class A:\n    def __init__(self): print('A')\nclass B(A):\n    def __init__(self):\n        super().__init__()\n        print('B')\n\nB()", "A\nB", ["B\nA", "B", "A"], "super().__init__() runs the base initialiser first, then the rest of B's own code."),
        O("super", "hard", "What is printed?", "class A:\n    def go(self): print('A')\nclass B(A):\n    def go(self):\n        print('B'); super().go()\nclass C(A):\n    def go(self):\n        print('C'); super().go()\nclass D(B, C):\n    def go(self):\n        print('D'); super().go()\n\nD().go()", "D\nB\nC\nA", ["D\nB\nA", "D\nB\nA\nC", "D\nC\nB\nA"], "super() follows the MRO (D, B, C, A), so B's super() reaches C, not A: cooperative multiple inheritance."),
        O("dataclasses", "medium", "What is printed?", "from dataclasses import dataclass\n@dataclass\nclass P:\n    x: int\n    y: int = 0\n\nprint(P(1), P(1) == P(1, 0))", "P(x=1, y=0) True", ["<P object> False", "P(1, 0) True", "P(x=1) True"], "@dataclass generates __init__, __repr__ and __eq__ from the annotated fields."),
        M("dataclasses", "hard", "Why is `tags: list = []` rejected in a dataclass?", "Mutable defaults are shared between instances, so dataclass raises ValueError; use field(default_factory=list)", ["Lists are not allowed as field types", "Defaults must be strings", "It is allowed and creates a new list per instance"], "dataclasses forbid list, dict and set defaults for exactly the shared-default reason; default_factory builds a fresh one per instance."),
        O("lifecycle-gc", "medium", "What is printed (CPython)?", "import sys\na = []\nb = a\nprint(sys.getrefcount(a) - 1, end=' ')\ndel b\nprint(sys.getrefcount(a) - 1)", "2 1", ["1 1", "2 2", "3 1"], "getrefcount includes the temporary argument reference, so subtract 1: a and b give 2, then 1 after del b.", py="3.12 (CPython)"),
        M("lifecycle-gc", "medium", "What does CPython use besides reference counting to reclaim objects?", "A cyclic garbage collector that finds unreachable reference cycles", ["Manual free() calls by the programmer", "A mark-and-sweep that runs on every statement", "Nothing; cycles are leaked forever"], "Reference counting frees most objects immediately; the gc module's generational collector reclaims cycles."),
    ]
